data.document:
query NativeMLModelQuery($client_capability_metadata, $model_request_metadatas) {
  name
  aim_model_batched_manifest {
    models {
      version
      assets {
        id
        cache_key
        source_content_hash
        md5_hash
        asset_handle
        creation_time
        url
        filesize_bytes
        compression_type
        asset_type
        properties {
          value
          entry_point
          asset_count
          model_count
          status
          status_details
        }
      }
    }
  }
}
